import { describe, expect, it } from "bun:test";
import { webhookStubFor } from "./phantom-wire.ts";

describe("webhook stub closing braces", () => {
  it("preserves a lone closing brace and its surrounding interpolated prose", () => {
    const stub = webhookStubFor("before}after");

    expect(stub.split("\n")[0]).toBe(
      "// Auto-generated by `stack apply` — webhook handler stub for before}after.",
    );
    expect(stub).toContain("//   // to this endpoint can forge a before}after webhook.\n");
    expect(stub).toContain(
      '//   // parse, trust, or act on the body.\n//   return new Response("ok", { status: 200 });\n// }\n',
    );
  });
});
